/**
 * Port of test19.py:
 *
 *     m1 = Money(args.amount1, args.currency)
 *     m2 = Money(args.amount2, args.currency)
 *     smaller = m1 if m1 < m2 else m2
 *     print(smaller)
 *
 * Run as: node test19.mjs --amount1 <float> --amount2 <float> --currency <code>
 */
import { ArgumentParser } from './lib/argparse.mjs';
import { pyFloat } from './lib/pyfloat.mjs';
import { pyRepr } from './lib/pyrepr.mjs';
import { Money } from './lib/money.mjs';
import { CurrencyDoesNotExist, InvalidOperation, abortWithTraceback } from './lib/errors.mjs';

/**
 * argparse derives `prog` from `basename(sys.argv[0])`. The reference build is a
 * PyInstaller binary called `test19_executable`, so that is the name its usage and
 * error messages carry, and the name this port reproduces.
 */
const PROG = 'test19_executable';

const parser = new ArgumentParser(PROG);
parser.addArgument('--amount1', { type: pyFloat, required: true });
parser.addArgument('--amount2', { type: pyFloat, required: true });
parser.addArgument('--currency', { required: true });
const args = parser.parseArgs(process.argv.slice(2));

// Frames the reference prints when an exception escapes, keyed by the source line
// of test19.py that raised.
const CONSTRUCT_FRAMES = [
  ['test19.py', 11, '<module>'],
  ['moneyed/classes.py', 196, '__init__'],
  ['moneyed/classes.py', 402, 'get_currency'],
];
const COMPARE_FRAMES = [
  ['test19.py', 14, '<module>'],
  ['moneyed/classes.py', 339, '__lt__'],
];
const PRINT_FRAMES = [
  ['test19.py', 19, '<module>'],
  ['moneyed/classes.py', 203, '__str__'],
  ['moneyed/l10n.py', 23, 'format_money'],
  ['babel/numbers.py', 833, 'format_currency'],
  ['babel/numbers.py', 1547, 'apply'],
  ['babel/numbers.py', 1647, '_quantize_value'],
];

/** Run `body`, rendering a Python traceback and exiting 1 if it raises. */
function pythonFrame(frames, body, cause) {
  try {
    return body();
  } catch (err) {
    if (err instanceof CurrencyDoesNotExist || err instanceof InvalidOperation) {
      abortWithTraceback(err, frames, cause ? cause(err) : undefined);
    }
    throw err;
  }
}

const [m1, m2] = pythonFrame(
  CONSTRUCT_FRAMES,
  () => [new Money(args.amount1, args.currency), new Money(args.amount2, args.currency)],
  // get_currency re-raises a KeyError as CurrencyDoesNotExist, so the reference
  // shows the original KeyError as the chained cause.
  err => ({
    pyType: 'KeyError',
    message: pyRepr(err.code),
    frames: [['moneyed/classes.py', 400, 'get_currency']],
  }),
);

const smaller = pythonFrame(COMPARE_FRAMES, () => (m1.lessThan(m2) ? m1 : m2));

process.stdout.write(pythonFrame(PRINT_FRAMES, () => String(smaller)) + '\n');
=====ARGPARSE=====
/**
 * The slice of `argparse.ArgumentParser` this program relies on: long options only,
 * `store` and `help` actions, prefix abbreviation, and argparse's exact error text
 * and exit statuses (2 for a usage error, 0 for `--help`).
 */
import { formatUsage, formatHelp } from './help_formatter.mjs';
import { pyRepr } from './pyrepr.mjs';

/**
 * argparse's negative-number heuristic. With no negative-number-like options
 * declared, a token matching this is a value rather than an option, which is what
 * lets `--amount1 -5` work while `--currency -USD` does not.
 */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  if (token.length <= 1 || token[0] !== '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return !token.includes(' ');
}

export class ArgumentParser {
  /**
   * @param {string} prog name shown in usage and error lines
   */
  constructor(prog) {
    this.prog = prog;
    this.actions = [
      {
        dest: 'help',
        optionStrings: ['-h', '--help'],
        nargs: 0,
        required: false,
        help: 'show this help message and exit',
      },
    ];
  }

  addArgument(optionString, { type, required = false, metavar } = {}) {
    const dest = optionString.replace(/^--/, '').replace(/-/g, '_');
    this.actions.push({
      dest,
      optionStrings: [optionString],
      nargs: 1,
      required,
      type,
      metavar: metavar ?? dest.toUpperCase(),
      help: '',
    });
    return this;
  }

  /** `parser.error(message)`: usage + error line on stderr, exit 2. */
  error(message) {
    process.stderr.write(formatUsage(this.prog, this.actions) + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelpAndExit() {
    process.stdout.write(formatHelp(this.prog, this.actions));
    process.exit(0);
  }

  /**
   * Resolve a long-option token to its action, honouring unique-prefix
   * abbreviation. Returns null when nothing matches.
   */
  #matchLongOption(flag, rawToken) {
    const candidates = [];
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString === flag) return { action, optionString };
        if (optionString.startsWith('--') && optionString.startsWith(flag)) {
          candidates.push({ action, optionString });
        }
      }
    }
    if (candidates.length > 1) {
      const names = candidates.map(c => c.optionString).join(', ');
      this.error(`ambiguous option: ${rawToken} could match ${names}`);
    }
    return candidates.length === 1 ? candidates[0] : null;
  }

  /**
   * argparse classifies every token up front — before running a single action —
   * to build its option/positional pattern. Abbreviation is resolved during that
   * sweep, so an ambiguous prefix aborts the whole parse no matter where it sits:
   * it outranks `-h`, an invalid float, and a missing value alike. Tokens from the
   * first `--` onward are pre-marked as positional and skipped.
   */
  #rejectAmbiguousOptions(argv) {
    for (const token of argv) {
      if (token === '--') return;
      if (!token.startsWith('--') || token.length === 2) continue;
      const eq = token.indexOf('=');
      this.#matchLongOption(eq === -1 ? token : token.slice(0, eq), token);
    }
  }

  /**
   * Handle a single-dash token beginning with `-h`.
   *
   * argparse tries to peel further single-dash flags off the tail, so `-hx` runs
   * help and leaves `-x` behind. It refuses when the tail was introduced by `=` or
   * itself starts with a prefix character, which is why `-h=x` and `-h-x` are errors
   * while `-hx` and `-hh` are not.
   */
  #consumeHelpToken(token) {
    const eq = token.indexOf('=');
    const tail = eq === -1 ? token.slice(2) : token.slice(eq + 1);
    const introducedByEquals = eq !== -1;
    if (tail !== '' && (introducedByEquals || tail[0] === '-')) {
      const names = this.actions[0].optionStrings.join('/');
      this.error(`argument ${names}: ignored explicit argument ${pyRepr(tail)}`);
    }
    if (tail === '' && introducedByEquals) {
      const names = this.actions[0].optionStrings.join('/');
      this.error(`argument ${names}: ignored explicit argument ${pyRepr('')}`);
    }
    this.printHelpAndExit();
  }

  /**
   * Parse `argv` (the tokens after the program name) into a values object,
   * exiting the process on any error, exactly as argparse does.
   */
  parseArgs(argv) {
    this.#rejectAmbiguousOptions(argv);

    const values = Object.create(null);
    const extras = [];
    let i = 0;

    while (i < argv.length) {
      const token = argv[i];

      if (token === '--') {
        // argparse marks `--` and everything after it as positional. With no
        // positionals declared, nothing consumes them — the `--` itself included —
        // so they all surface as unrecognized arguments.
        extras.push(...argv.slice(i));
        i = argv.length;
        break;
      }

      if (token.startsWith('-h') && !token.startsWith('--')) {
        this.#consumeHelpToken(token);
      }

      if (!token.startsWith('--')) {
        extras.push(token);
        i += 1;
        continue;
      }

      const eq = token.indexOf('=');
      const flag = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? null : token.slice(eq + 1);

      const match = this.#matchLongOption(flag, token);
      if (match === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      const { action, optionString } = match;

      if (action.nargs === 0) {
        if (explicitValue !== null) {
          const names = action.optionStrings.join('/');
          this.error(`argument ${names}: ignored explicit argument ${pyRepr(explicitValue)}`);
        }
        this.printHelpAndExit();
      }

      let raw;
      if (explicitValue !== null) {
        raw = explicitValue;
        i += 1;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        raw = next;
        i += 2;
      }

      if (action.type) {
        const converted = action.type(raw);
        if (converted === null) {
          this.error(`argument ${optionString}: invalid float value: ${pyRepr(raw)}`);
        }
        values[action.dest] = converted;
      } else {
        values[action.dest] = raw;
      }
    }

    // Required options are reported before leftover tokens, in definition order.
    const missing = this.actions
      .filter(a => a.required && !(a.dest in values))
      .map(a => a.optionStrings.join('/'));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}
=====HELP=====
/**
 * Usage and help rendering, following `argparse.HelpFormatter`.
 *
 * The wrapping is reproduced rather than hard-coded because the break point is
 * load-bearing: with a 17-character prog name the reference splits *between*
 * `--currency` and `CURRENCY`, since required options are printed unbracketed and
 * argparse's usage tokenizer treats a flag and its metavar as separate wrap tokens.
 */

/** argparse reads the terminal width and formats to `columns - 2`. */
function textWidth() {
  const columns = Number.parseInt(process.env.COLUMNS ?? '', 10);
  return (Number.isNaN(columns) ? 80 : columns) - 2;
}

/** `HelpFormatter._get_lines`: greedily pack parts, wrapping at the text width. */
function packLines(parts, indent, prefix) {
  const width = textWidth();
  const lines = [];
  let line = [];
  let lineLen = prefix.length - 1;

  for (const part of parts) {
    if (line.length && lineLen + 1 + part.length > width) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length) lines.push(indent + line.join(' '));
  if (lines.length) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** `'--amount1 AMOUNT1'` / `'-h, --help'` — how an option is shown in the options list. */
function invocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map(o => `${o} ${action.metavar}`).join(', ');
}

/** How an option is shown in the usage line: only its *first* option string. */
function usageInvocation(action) {
  const first = action.optionStrings[0];
  return action.nargs === 0 ? first : `${first} ${action.metavar}`;
}

/** The `usage: ...` block, without a trailing newline. */
export function formatUsage(prog, actions) {
  const parts = [];
  for (const action of actions) {
    const text = action.required
      ? usageInvocation(action)
      : `[${usageInvocation(action)}]`;
    // argparse splits usage into bracketed groups and bare words; an unbracketed
    // `--currency CURRENCY` therefore contributes two independently wrappable tokens.
    parts.push(...(text.match(/\(.*?\)+|\[.*?\]+|\S+/g) || []));
  }

  const prefix = 'usage: ';
  const oneLine = `${prefix}${prog} ${parts.join(' ')}`;
  if (oneLine.length <= textWidth()) return oneLine;

  // Prog is short enough to keep on the first line and hang the rest under it.
  if (prefix.length + prog.length <= Math.floor(0.75 * textWidth())) {
    const indent = ' '.repeat(prefix.length + prog.length + 1);
    return prefix + packLines([prog, ...parts], indent, prefix).join('\n');
  }
  const indent = ' '.repeat(prefix.length);
  return `${prefix}${prog}\n` + packLines(parts, indent, indent).map(l => indent + l).join('\n');
}

/** The full `--help` text, with a trailing newline. */
export function formatHelp(prog, actions) {
  const indent = 2;
  const maxHelpPosition = 24;
  const invocations = actions.map(invocation);
  const actionMaxLength = Math.max(...invocations.map(i => i.length + indent));
  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);

  const lines = [formatUsage(prog, actions), '', 'options:'];
  for (const [i, action] of actions.entries()) {
    const shown = ' '.repeat(indent) + invocations[i];
    if (!action.help) {
      lines.push(shown);
      continue;
    }
    if (shown.length < helpPosition) {
      lines.push(shown + ' '.repeat(helpPosition - shown.length) + action.help);
    } else {
      lines.push(shown, ' '.repeat(helpPosition) + action.help);
    }
  }
  return lines.join('\n') + '\n';
}
